"""Build Spanish OAQ pages from the authored syllabus-aligned lesson source."""
import sys
sys.dont_write_bytecode = True
import html,json
from pathlib import Path
from oaq_content import LEVELS,UNITS
ROOT=Path(__file__).resolve().parent.parent
E=lambda v:html.escape(str(v),quote=True)
def dump(v):return json.dumps(v,ensure_ascii=False,indent=2)
def header(prefix,level=''):
 return f'''<a class="skip" href="#main">Saltar al contenido</a><header class="topbar"><a class="brand" href="{prefix}index.html"><img src="{prefix}assets/brand/learning-lab-logo.png" width="44" height="44" alt="">learning<span>lab</span></a><nav aria-label="Navegación principal"><a href="{prefix}index.html#/years">Años y programas</a><a href="{prefix}activities/oaq/" aria-current="{ 'page' if not level else 'false'}">OAQ</a><a href="{prefix}activities/oaq/programa.html#como-estudiar">Cómo estudiar</a></nav></header>'''
def shell(title,prefix,body,script='',level=''):
 return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#153c46"><meta name="description" content="{E(title)}. Preparación autónoma de química en español, ejemplos, repaso y laboratorio virtual."><title>{E(title)} | OAQ · Learning Lab</title><link rel="icon" type="image/png" href="{prefix}assets/brand/learning-lab-logo.png"><link rel="stylesheet" href="{prefix}assets/oaq/oaq.css?v=1"><link rel="stylesheet" href="{prefix}assets/desktop-layout.css?v=desktop-1">{script}</head><body>{header(prefix,level)}{body}<footer class="footer"><span>Learning Lab · Química para entender y explorar</span><a href="{prefix}activities/oaq/programa.html">Programa y fuente</a></footer><noscript><p class="notice">Las explicaciones y los ejemplos se pueden leer sin JavaScript. Activá JavaScript para usar los laboratorios, corregir respuestas y guardar el avance.</p></noscript></body></html>'''
def save(path,text):
 path=ROOT/path;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text,encoding='utf-8')
def card(unit,href):
 return f'''<a class="unit-tile" href="{href}"><span class="tag">SERIE {unit['series']} · 4 LECCIONES</span><h2>{E(unit['title'])}</h2><p>{E(' · '.join(l['title'] for l in unit['lessons']))}</p><span class="tile-end">Lecciones + laboratorio + repaso <b aria-hidden="true">↗</b></span><small data-progress="{unit['id']}">0 de 4 lecciones comprobadas</small></a>'''
levelmap={l['id']:l for l in LEVELS}
for unit in UNITS:
 for i,lesson in enumerate(unit['lessons']):
  lesson['check']['area']=i
  lesson['check']['level']='Fundamentos' if i<2 else 'Aplicación'
 for i,q in enumerate(unit['review']):
  q['level']='Aplicación' if i<3 else 'Desafío'
 unit['path']=f"{unit['level']}/serie-{unit['series']}/"
save(Path('assets/oaq/course.json'),dump({'levels':LEVELS,'units':UNITS})+'\n')
progressscript='<script type="module" src="../../assets/oaq/progress.js?v=1"></script>'
levels=''.join(f'''<a class="level-tile" href="{l['id']}/"><span class="tag">OAQ · 4 SERIES</span><img src="{l['id']}/cover.svg" alt="" width="360" height="180"><h2>{l['name']}</h2><p>{E(l['intro'])}</p><span class="tile-end">Elegir una unidad <b>→</b></span></a>''' for l in LEVELS)
body=f'''<main id="main"><section class="oaq-hero"><div><p class="eyebrow">OLIMPÍADA ARGENTINA DE QUÍMICA · PREPARACIÓN EN ESPAÑOL</p><h1>Entendé la química.<br><em>Explorá cómo funciona.</em></h1><p>Una ruta para estudiar a tu ritmo: explicaciones, ejemplos resueltos y experimentos virtuales que vos hacés funcionar.</p><a class="button" href="#niveles">Elegí tu nivel ↓</a></div><div class="hero-art"><img src="nivel-inicial/cover.svg" alt="Ilustración de material de laboratorio y moléculas"><span>OBSERVAR → MODELAR → EXPLICAR</span></div></section><section id="niveles"><div class="section-title"><span>01</span><div><p class="eyebrow">TU PUNTO DE PARTIDA</p><h2>Tres niveles. Un camino acumulativo.</h2></div></div><p>Comenzá por Nivel Inicial o usá la orientación de abajo para elegir qué estudiar primero. Nivel 1 incluye los contenidos del Inicial; Nivel 2 incluye los de ambos anteriores.</p><details class="diagnostic"><summary>¿Por dónde empiezo? Tres ideas para orientarte.</summary><p>Esta orientación elige una ruta de estudio. No asigna un nivel oficial de inscripción.</p><form id="orientation-form"><fieldset><legend>1. Si duplicás una muestra de agua pura a igual temperatura, ¿qué permanece igual?</legend><label><input type="radio" name="orientation-0" value="0" required>La densidad</label><label><input type="radio" name="orientation-0" value="1">La masa</label></fieldset><fieldset><legend>2. En 2 H₂ + O₂ → 2 H₂O, con 3 mol H₂ y 1 mol O₂, ¿qué se agota primero?</legend><label><input type="radio" name="orientation-1" value="0" required>H₂</label><label><input type="radio" name="orientation-1" value="1">O₂</label></fieldset><fieldset><legend>3. Si Q &lt; K a temperatura fija, ¿hacia dónde evoluciona la reacción escrita?</legend><label><input type="radio" name="orientation-2" value="0" required>Hacia productos</label><label><input type="radio" name="orientation-2" value="1">Hacia reactivos</label></fieldset><button class="button" type="submit">Mostrar mi punto de partida →</button><div id="orientation-result" role="status"></div></form></details><div class="level-grid">{levels}</div></section><section class="study-path"><div class="section-title"><span>02</span><div><p class="eyebrow">CÓMO ESTUDIAR POR TU CUENTA</p><h2>Una rutina para cada unidad.</h2></div></div><div class="three-grid"><article><h3>Leé y razoná</h3><p>Revisá los requisitos, estudiá una explicación y resolvé el ejemplo antes de abrir la solución. Comprobá una idea a la vez.</p></article><article><h3>Hacé el experimento</h3><p>Predecí, mové el material y operá los instrumentos sobre la mesa. Registrá medidas y compará con el modelo.</p></article><article><h3>Practicá y retomá</h3><p>Recibí explicaciones de tus respuestas. El avance se guarda en este navegador; podés volver a las ideas que te cuestan.</p></article></div></section><aside class="notice"><strong>Sobre esta preparación.</strong> Material original de Learning Lab organizado a partir del Anexo II del reglamento compartido; no es una publicación oficial de OAQ. <a href="programa.html">Ver correspondencia con el programa</a>. 2-bis y 3 quedan para una próxima ampliación. El progreso y los resultados de este módulo se guardan solo en este navegador.</aside></main>'''
save(Path('activities/oaq/index.html'),shell('OAQ · Estudiá y experimentá','../../',body,progressscript))
for j,l in enumerate(LEVELS):
 units=[u for u in UNITS if u['level']==l['id']];prefix='../../../'
 colors=['#74c9bd','#edb66e','#b9a3e3'];color=colors[j]
 cover=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 300"><rect width="600" height="300" rx="24" fill="#153c46"/><circle cx="455" cy="100" r="100" fill="{color}" opacity=".12"/><path d="M160 65h75m-58 0v75l-50 95q-7 16 13 16h120q20 0 13-16l-50-95V65" fill="#e3f5f026" stroke="#b9e4da" stroke-width="4"/><path d="M153 183h95l30 56H123Z" fill="{color}"/><circle cx="190" cy="192" r="7" fill="#fff" opacity=".6"/><circle cx="221" cy="214" r="9" fill="#fff" opacity=".5"/><path d="M335 92l100 48-26 85-106-8Z" fill="none" stroke="#99c0c6" stroke-width="4"/><g fill="{color}" stroke="#edfff8" stroke-width="3"><circle cx="335" cy="92" r="18"/><circle cx="435" cy="140" r="22"/><circle cx="409" cy="225" r="14"/><circle cx="303" cy="217" r="17"/></g><text x="40" y="40" fill="#c6e6e0" font-family="sans-serif" font-size="13" letter-spacing="3">LEARNING LAB / OAQ</text><text x="335" y="277" fill="{color}" font-family="sans-serif" font-size="22">{l['name']}</text></svg>'''
 save(Path(f"activities/oaq/{l['id']}/cover.svg"),cover)
 prerequisites='Comenzá con unidades, fracciones, proporciones y potencias de diez.' if not l['inherits'] else 'Antes de empezar, repasá '+', '.join(f'<a href="../{p}/">{levelmap[p]["name"]}</a>' for p in l['inherits'])+'. Los contenidos se acumulan.'
 tabs=''.join(f'<a href="../{v["id"]}/" {"aria-current=\"page\"" if v==l else ""}>{v["name"]}</a>' for v in LEVELS)
 b=f'''<main id="main"><nav class="crumbs" aria-label="Recorrido"><a href="../">OAQ</a><span>›</span><span>{l['name']}</span></nav><nav class="level-tabs" aria-label="Niveles">{tabs}</nav><section class="level-heading"><div><p class="eyebrow">OAQ · ESTUDIO AUTÓNOMO</p><h1>{l['name']}</h1><p>{l['intro']}</p><p class="prerequisite"><strong>Punto de partida.</strong> {prerequisites}</p></div><img src="cover.svg" width="350" height="180" alt=""></section><div class="section-title"><span>01</span><div><p class="eyebrow">SEGUÍ EL ORDEN O ELEGÍ QUÉ REPASAR</p><h2>Las cuatro series del nivel.</h2></div></div><div class="unit-grid">{''.join(card(u,f'serie-{u["series"]}/') for u in units)}</div><aside class="notice">Cada serie tiene cuatro lecciones, un laboratorio con cuaderno de resultados y ocho preguntas de repaso. Las marcas indican respuestas comprobadas en este navegador, no una certificación del dominio del tema. <a href="../programa.html">Ver el mapa del programa.</a></aside></main>'''
 save(Path(f"activities/oaq/{l['id']}/index.html"),shell(l['name'],'../../../',b,'<script type="module" src="../../../assets/oaq/progress.js?v=1"></script>',l['id']))
prerequisites={
 'nivel-inicial-serie-1':('Necesitás dividir, usar proporciones y convertir unidades sencillas. Si es tu primer encuentro con química, empezá por la primera lección.','nivel-inicial/serie-1/'),
 'nivel-inicial-serie-2':('Antes: distinguí átomos, elementos, iones y sustancias; revisá Z y cargas de la serie 1.','nivel-inicial/serie-1/'),
 'nivel-inicial-serie-3':('Antes: leé fórmulas y coeficientes; practicá reglas de tres y potencias de diez. Repasá las ecuaciones de la serie 2 si lo necesitás.','nivel-inicial/serie-2/'),
 'nivel-inicial-serie-4':('Antes: convertí gramos a moles y aplicá proporciones de una ecuación balanceada.','nivel-inicial/serie-3/'),
 'nivel-1-serie-1':('Antes: usá n = m/M, PV = nRT y c = n/V. Si estas relaciones no te resultan familiares, repasá las series 3 y 4 de Inicial.','nivel-inicial/serie-4/'),
 'nivel-1-serie-2':('Antes: contá electrones de valencia y reconocé grupos y períodos; revisá átomos e iones.','nivel-inicial/serie-1/'),
 'nivel-1-serie-3':('Antes: balanceá ecuaciones y calculá cantidades en solución. Distinguí sistema y entorno para interpretar signos.','nivel-inicial/serie-4/'),
 'nivel-1-serie-4':('Antes: asigná estados de oxidación, convertí concentraciones y repasá neutralización. Para logaritmos usá la calculadora y recordá log(10ⁿ) = n.','nivel-1/serie-3/'),
 'nivel-2-serie-1':('Antes: dominá gases ideales, concentración, disociación y reactivo limitante de Nivel 1.','nivel-1/serie-1/'),
 'nivel-2-serie-2':('Antes: dibujá Lewis, contá regiones electrónicas y distinguí fuerzas entre moléculas y enlaces dentro de ellas.','nivel-1/serie-2/'),
 'nivel-2-serie-3':('Antes: aplicá q = mcΔT, interpretá ΔH y balanceá reacciones. Usá kelvin y convertí J a kJ con cuidado.','nivel-1/serie-3/'),
 'nivel-2-serie-4':('Antes: resolvé moles de neutralización, interpretá pH y usá ΔG para distinguir termodinámica de rapidez.','nivel-1/serie-4/')}
for u in UNITS:
 l=levelmap[u['level']];prefix='../../../../'
 lessons='';lessonlinks=''
 for i,lesson in enumerate(u['lessons']):
  lessonlinks+=f'<a href="#leccion-{i+1}" data-lesson-link="{i}" {"aria-current=\"page\"" if i==0 else ""}><span>{i+1:02}</span>{E(lesson["title"])}<small data-complete="{i}" aria-label="Pendiente">○</small></a>'
  examples=''.join(f'<li>{E(v)}</li>' for v in lesson['example'][1:])
  options=''.join(f'<button type="button" data-answer="{a}">{E(opt)}</button>' for a,opt in enumerate(lesson['check']['options']))
  lessons+=f'''<article class="lesson-card" id="leccion-{i+1}" data-lesson="{i}"><p class="eyebrow">LECCIÓN {i+1} / 4 · LEÉ, RESOLVÉ Y COMPROBÁ</p><h3>{E(lesson['title'])}</h3>{''.join('<p>'+E(p)+'</p>' for p in lesson['text'])}<div class="formula">{E(lesson['formula'])}</div><div class="worked-problem"><span class="tag">TU TURNO · INTENTÁ RESOLVER ANTES DE MIRAR</span><p>{E(lesson['example'][0])}</p><p><strong>Tu desafío:</strong> {E(lesson['task'])}</p></div><details class="worked"><summary>Ver el ejemplo resuelto paso a paso</summary><ol>{examples}</ol></details><aside class="memory"><span class="tag">PARA RECORDAR Y ENTENDER</span><h4>{E(lesson['memory']['cue'])}</h4><p>{E(lesson['memory']['reason'])}</p></aside><aside class="trap"><strong>Prestá atención.</strong> {E(lesson['trap'])}</aside><fieldset class="lesson-check" data-check="{i}"><legend>{E(lesson['check']['prompt'])}</legend><button type="button" class="button secondary" data-hint="{i}" aria-expanded="false">Necesito una pista</button><p class="hint-feedback" data-hint-text="{i}" hidden>Recordá: {E(lesson['memory']['cue'])} Revisá esta relación: {E(lesson['formula'])}.</p><div class="answers">{options}</div><p class="feedback" role="status"></p></fieldset><button class="button secondary lesson-next" data-next="{i+1}">{'Siguiente lección →' if i<3 else 'Ir al laboratorio ↓'}</button></article>'''
 b=f'''<main id="main" data-unit="{u['id']}"><nav class="crumbs" aria-label="Recorrido"><a href="../../">OAQ</a><span>›</span><a href="../">{l['name']}</a><span>›</span><span>Serie {u['series']}</span></nav><section class="unit-heading"><p class="eyebrow">{l['name'].upper()} · SERIE {u['series']}</p><h1>{E(u['title'])}</h1><p>Estudiá las cuatro lecciones, explicá tus observaciones en el laboratorio y poné a prueba lo que aprendiste.</p><div class="progress-strip"><progress id="unit-progress" max="4" value="0" aria-label="Lecciones comprobadas"></progress><span id="progress-label">0 de 4 lecciones comprobadas</span><span id="storage-note">Avance guardado solo en este navegador</span></div></section><aside class="unit-prerequisites"><strong>Antes de empezar.</strong> {E(prerequisites[u['id']][0])} <a href="../../{prerequisites[u['id']][1]}">Ir al repaso previo →</a><br><strong>Meta:</strong> resolver los cuatro controles, completar un ensayo y comparar dos condiciones en la investigación guiada. Podés avanzar, consultar pistas y volver a cualquier lección.</aside><details class="syllabus"><summary>Qué incluye esta serie · correspondencia con el Anexo II</summary><ul>{''.join('<li>'+E(t)+'</li>' for t in u['topics'])}</ul><p>Fuente: {l['name']}, serie {u['series']}, páginas {l['pages']} del reglamento compartido. <a href="../../programa.html">Mapa y alcance de las lecciones</a>.</p></details><section id="estudiar"><div class="section-title"><span>01</span><div><p class="eyebrow">COMPRENDÉ LA IDEA</p><h2>Tu ruta de estudio.</h2></div></div><div class="study-layout"><nav class="lesson-nav" aria-label="Lecciones de esta serie">{lessonlinks}<a href="#laboratorio"><span>LAB</span>Laboratorio guiado</a><a href="#repaso"><span>✓</span>Repaso de la unidad</a><a href="../">← Todas las series</a></nav><div id="lesson-content">{lessons}</div></div></section><section id="laboratorio"><div class="section-title"><span>02</span><div><p class="eyebrow">PREDECÍ · INVESTIGÁ · EXPLICÁ</p><h2>La química en tus manos.</h2></div></div><div id="oaq-lab"><p role="status">Cargando la mesa de trabajo…</p></div></section><section id="repaso" class="review-section"><div class="section-title"><span>03</span><div><p class="eyebrow">LISTO PARA PONER A PRUEBA TU COMPRENSIÓN</p><h2>Repasá y encontrá qué volver a estudiar.</h2></div></div><p>Ocho preguntas por unidad, con explicación y enlace a la lección correspondiente. Estos resultados se guardan únicamente en este navegador; no se envían al panel docente.</p><div id="review-app"></div></section><nav class="unit-bottom" aria-label="Continuar el estudio"><a class="button secondary" href="../">← Volver a {l['name']}</a>{f'<a class="button" href="../serie-{u["series"]+1}/">Continuar con la serie {u["series"]+1} →</a>' if u['series']<4 else '<a class="button" href="../../">Elegir otro nivel →</a>'}</nav></main><script type="application/json" id="unit-data">{dump(u).replace('<', chr(92)+'u003c')}</script>'''
 save(Path(f"activities/oaq/{u['path']}/index.html"),shell(f"{l['name']} · Serie {u['series']}: {u['title']}",prefix,b,f'<script type="module" src="{prefix}assets/oaq/lesson.js?v=1"></script>',l['id']))
# A readable coverage map makes the source and the cumulative structure explicit.
rows=''.join(f'<tr><th scope="row">{levelmap[u["level"]]["name"]}<br>Serie {u["series"]}</th><td><a href="{u["path"]}">{E(u["title"])}</a><ul>'+''.join('<li>'+E(t)+'</li>' for t in u['topics'])+f'</ul></td><td>{levelmap[u["level"]]["pages"]}</td></tr>' for u in UNITS)
b=f'''<main id="main"><nav class="crumbs"><a href="./">OAQ</a><span>›</span><span>Programa y fuente</span></nav><section class="unit-heading"><p class="eyebrow">CORRESPONDENCIA CON EL REGLAMENTO</p><h1>Qué estudiamos y de dónde sale.</h1><p>Organización basada en el Anexo II, «Niveles, contenidos y destinatarios», del archivo <cite>Reglamento_Operativo_OAQ (3).pdf</cite> compartido por el docente. Se indican las páginas impresas del documento. Las explicaciones, problemas y modelos son material original de Learning Lab, independiente de la organización oficial.</p></section><aside class="notice"><strong>Hasta Nivel 2.</strong> Esta primera entrega incluye Inicial, 1 y 2. El temario es acumulativo; 2-bis y 3 se incorporarán después. La asignación del nivel y la vigencia del reglamento deben confirmarse con el coordinador; esta plataforma no asigna niveles automáticamente por edad o curso.</aside><div class="section-title"><span>01</span><div><h2>Mapa de las doce unidades.</h2></div></div><div class="table-wrap"><table><thead><tr><th>Nivel y serie</th><th>Contenidos del anexo y unidad de estudio</th><th>Páginas</th></tr></thead><tbody>{rows}</tbody></table></div><section id="como-estudiar"><h2>Cómo estudiar sin ayuda de un profesor</h2><ol><li>Elegí un nivel con la orientación de la página OAQ y revisá el punto de partida de la serie.</li><li>Leé una lección, conectá la regla para recordar con su explicación y resolvé el ejemplo en papel antes de abrir los pasos.</li><li>Comprobá la idea. Si te equivocás, leé la devolución, pedí una pista y volvé a intentarlo.</li><li>En la mesa virtual, guardá una predicción, seguí las instrucciones y mové el material. La ayuda hace solo el paso que estás trabajando.</li><li>Registrá dos ensayos siguiendo la investigación: cambiá la variable indicada y mantené las demás. Compará los resultados y respondé por qué cambian.</li><li>Terminá con práctica o autoevaluación. Usá «Practicar solo los errores» y los enlaces a las lecciones para resolver tus dudas.</li></ol><h2>Alcance de este material</h2><p>Las lecciones presentan modelos y ejemplos para iniciar o consolidar cada serie. El mapa permite ubicar cada contenido del anexo; los mecanismos y cálculos más extensos requieren seguir practicando con las series oficiales y sus correcciones. Las preguntas de esta plataforma son originales y no constituyen exámenes oficiales.</p><p>En el reglamento compartido, Inicial incorpora series 1–2 para el Colegial, 1–3 para Intercolegial y 1–4 para Zonal. En Niveles 1 y 2 se incorpora la serie 1 para Colegial, 1–2 para Intercolegial, 1–3 para Zonal y 1–4 para Nacional (apartado B, página 15). Esta ruta permite estudiar cada serie completa y no bloquea contenidos por certamen.</p><h2>Modelos experimentales</h2><p>Se explicitan hipótesis, unidades y aproximaciones en cada mesa. Las animaciones aceleran procesos; no predicen tiempos reales salvo que se indique una ley cinética. Los talleres de geometría, balanceo y orbitales son representaciones, no mediciones de laboratorio. Las prácticas virtuales preparan el razonamiento y el uso del material; el trabajo real requiere el protocolo y la supervisión del laboratorio.</p><h2>Tu avance</h2><p>Las respuestas comprobadas, el cuaderno virtual y el último repaso se almacenan localmente en este navegador y dispositivo. No se piden datos personales ni se envían estos resultados a Google. Si usás navegación privada, borrás datos del sitio o cambiás de equipo, el avance puede no estar disponible.</p></section></main>'''
save(Path('activities/oaq/programa.html'),shell('Programa y fuente','../../',b))
# Catalogue entries keep the programme discoverable alongside the year groups.
p=ROOT/'catalog.json';catalog=json.loads(p.read_text());catalog['years']=[y for y in catalog['years'] if y['id']!='oaq'];subjects=[]
for l in LEVELS:
 topics=[]
 for u in [u for u in UNITS if u['level']==l['id']]:
  activity=dict(id=u['id'],title=u['title'],description='Cuatro lecciones en español, laboratorio guiado y ocho preguntas de repaso.',format='Lección y laboratorio',duration='A tu ritmo',image=f"activities/oaq/{l['id']}/cover.svg",href=f"activities/oaq/{u['path']}")
  topics.append(dict(id=f"serie-{u['series']}",name=f"Serie {u['series']}: {u['title']}",description=' · '.join(x['title'] for x in u['lessons']),primaryActivity=u['id'],appTitle=u['title'],activities=[activity]))
 subjects.append(dict(id=l['id'],name=l['name'],description=l['intro'],topics=topics))
catalog['years'].append(dict(id='oaq',name='Olimpíada Argentina de Química',shortName='OAQ',subjects=subjects))
p.write_text(dump(catalog)+'\n')
print(f"OAQ: {len(LEVELS)} niveles, {len(UNITS)} unidades, {sum(len(u['lessons']) for u in UNITS)} lecciones y {sum(len(u['lessons'])+len(u['review']) for u in UNITS)} preguntas de repaso.")
